		if not taskItem then
			return
		end
		local t = typeof and typeof(taskItem) or type(taskItem)
		if t == "thread" then
			pcall(function()
				if coroutine.status(taskItem) == "suspended" then
					task.cancel(taskItem)
				end
			end)
		elseif type(taskItem) == "function" then
			pcall(taskItem)
		elseif type(taskItem) == "table" then
			if type(taskItem.Disconnect) == "function" then
				pcall(taskItem.Disconnect, taskItem)
			elseif type(taskItem.Destroy) == "function" then
				pcall(taskItem.Destroy, taskItem)
			elseif type(taskItem.clean) == "function" then
				pcall(taskItem.clean, taskItem)
			end
		elseif t == "RBXScriptConnection" then
			pcall(function()
				taskItem:Disconnect()
			end)
		elseif t == "Instance" then
			pcall(function()
				taskItem:Destroy()
			end)
		end
	end

	function Maid.new()
		return setmetatable({ _tasks = {} }, Maid)
	end

	function Maid.__index(self, k)
