			return Maid[k]
		end
		return self._tasks[k]
	end

	function Maid.__newindex(self, k, v)
		if Maid[k] ~= nil then
			return warn(("'%s' is reserved"):format(tostring(k)), 2)
		end
		local tasks = self._tasks
		local old = tasks[k]
		if old == v then
			return
		end
		tasks[k] = v
		if old then
			cleanTask(old)
		end
	end

	function Maid:mark(obj)
		return self:add(obj)
	end

	function Maid:add(taskItem, key)
		if not taskItem then
			return taskItem
		end
		local id = key or (#self._tasks + 1)
		if self._tasks[id] and self._tasks[id] ~= taskItem then
			cleanTask(self._tasks[id])
		end
