	end

	function Signal:connect(name, callback)
		if not self.signal then
			return { Connected = false, Disconnect = function() end }
		end
		local wrapped = callback
		if Profiler and type(Profiler.wrap) == "function" and type(callback) == "function" then
			wrapped = Profiler.wrap(name or "Signal", callback)
		end
		local conn
		local ok, res = pcall(function()
			return self.signal:Connect(function(...)
				local sOk, err = xpcall(wrapped, debug.traceback, ...)
				if not sOk and Logger and Logger.trace then
					pcall(Logger.trace, "Signal(%s) error: %s", tostring(name), tostring(err))
				end
			end)
		end)
