		if not self.Open then
			self:ClosePopups()
			if self.Tooltip then
				self.Tooltip.Visible = false
			end
		end
		if self.MainFrame then
			self.MainFrame.Visible = self.Open and not self.Silent
		end
		self:SyncMouse()
	end

