				pcall(function()
					RunService:BindToRenderStep("MiraMenuMouse", Enum.RenderPriority.Last.Value, lockFreeMouse)
				end)
			end
			return
		end
		if mouseBound then
			mouseBound = false
			pcall(function()
				RunService:UnbindFromRenderStep("MiraMenuMouse")
			end)
		end
		settingMouse = true
		pcall(function()
			if UserInputService.MouseBehavior ~= prevMouseBehavior then
				UserInputService.MouseBehavior = prevMouseBehavior
			end
		end)
		settingMouse = false
	end

