			Name = "AccentLine",
			Size = UDim2.new(0, 2, 1, 0),
			BorderSizePixel = 0,
			ZIndex = 42,
			ThemeMap = { BackgroundColor3 = "AccentColor" },
			Parent = box,
		})
		self:Create("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.new(0, 8, 0, 0),
			Size = UDim2.new(1, -12, 0, 24),
			AutomaticSize = Enum.AutomaticSize.Y,
			FontFace = self.Font,
			TextSize = self.TextSize,
			RichText = true,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Text = msg,
			ZIndex = 42,
			ThemeMap = { TextColor3 = "FontColor" },
			Padding = { 4, 4, 0, 0 },
			Parent = box,
		})
		local dur = tonumber(duration) or 4
		if dur > 0 and task and task.delay then
			task.delay(dur, function()
				pcall(function()
					box:Destroy()
				end)
			end)
		end
	end

	function Library:ManuallyManagedNotify(text)
		self._notifSeq += 1
		self:Notify(text, 3)
		return {
			Close = function() end,
			Change = function() end,
		}
	end

	function Library:Unload()
		if self.Unloaded then
			return
		end
		self.Unloaded = true
		self:ClosePopups()
		if mouseBound then
			mouseBound = false
			pcall(function()
				RunService:UnbindFromRenderStep("MiraMenuMouse")
			end)
		end
		for _, conn in ipairs(self.Connections) do
			pcall(function()
				conn:Disconnect()
			end)
		end
		if self.ScreenGui then
			pcall(function()
				self.ScreenGui:Destroy()
			end)
		end
		if self.TooltipGui then
			pcall(function()
				self.TooltipGui:Destroy()
			end)
		end
	end

	local function placePopup(panel, anchorInst, w, h, anchorX)
		local pos = anchorInst and anchorInst.AbsolutePosition or Vector2.new(200, 200)
		local sz = anchorInst and anchorInst.AbsoluteSize or Vector2.new(160, 20)
		local x = anchorX == 1 and (pos.X + sz.X) or pos.X
		panel.Position = UDim2.fromOffset(x, pos.Y + sz.Y + 2)
		panel.Size = UDim2.fromOffset(w or sz.X, h or 120)
	end

	local function makeControlMethods(ctrl, onSet, addonsParent)
		ctrl.Callbacks = {}
		function ctrl:OnChanged(fn)
			if type(fn) == "function" then
				table.insert(self.Callbacks, fn)
			end
			return self
		end
		function ctrl:OnClick(fn)
			return self:OnChanged(fn)
		end
		function ctrl:SetValue(v)
			self.Value = v
			if self.Flag then
				Library.Flags[self.Flag] = v
			end
			if onSet then
				pcall(onSet, self, v)
			end
			for _, cb in ipairs(self.Callbacks) do
				pcall(cb, v)
			end
			Library:UpdateDependencyBoxes()
			return self
		end
		function ctrl:Display()
			if onSet then
				pcall(onSet, self, self.Value)
			end
		end
		function ctrl:_apply()
			self:Display()
		end

		function ctrl:AddKeyPicker(kpId, kpOpts)
			kpOpts = kpOpts or {}
			local kp = {
				Type = "KeyPicker",
				Flag = kpId,
				Text = kpOpts.Text or kpId,
				Value = kpOpts.Default or "N/A",
				Mode = kpOpts.Mode or "Toggle",
				SyncToggleState = kpOpts.SyncToggleState,
				NoList = kpOpts.NoList and true or false,
				State = false,
			}
			local keyText = formatKeyName(kp.Value)
			local badge
			if addonsParent then
				badge = Library:Create("TextButton", {
					Name = "TextButton",
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.new(1, 0, 0.5, 0),
					Size = UDim2.new(0, 30, 0, 16),
					AutomaticSize = Enum.AutomaticSize.X,
					FontFace = Library.Font,
					TextSize = 12,
					Text = keyText,
					TextXAlignment = Enum.TextXAlignment.Center,
					ZIndex = 3,
					DoubleBorder = true,
					ThemeMap = { BackgroundColor3 = "MainColor", TextColor3 = "FontColor" },
					Padding = { 0, 0, 6, 6 },
					Parent = addonsParent,
				})
			end
			makeControlMethods(kp, function(self, v)
				if badge then
					badge.Text = formatKeyName(v)
				end
				if Library.KeybindRows[kpId] then
					Library.KeybindRows[kpId].Key = v
					Library:RefreshKeybindList()
				end
			end)
			function kp:GetState()
				return self.State
			end
			function kp:Override(state)
				self.State = state and true or false
				if Library.KeybindRows[kpId] then
					Library.KeybindRows[kpId].Active = self.State
					Library:RefreshKeybindList()
				end
			end
			if kpOpts.Callback then
				kp:OnChanged(kpOpts.Callback)
			end

			local rowLbl = Library:Create("TextLabel", {
				Name = "TextLabel",
				LayoutOrder = 10,
				Size = UDim2.new(1, 0, 0, 20),
				BackgroundTransparency = 1,
				FontFace = Library.Font,
				TextSize = 16,
				TextXAlignment = Enum.TextXAlignment.Left,
				Text = string.format("%s  [%s]", tostring(kp.Text), keyText),
				Visible = false,
				ZIndex = 31,
				ThemeMap = { TextColor3 = "FontColor" },
				Parent = Library.KeybindFrame,
			})
			Library.KeybindRows[kpId] = {
				Label = rowLbl,
				Key = kp.Value,
				Text = kp.Text,
				Active = false,
				NoList = kp.NoList,
			}

			local listening = false
			if badge then
				badge.MouseButton1Click:Connect(function()
					listening = true
					badge.Text = "..."
					badge.TextColor3 = Library.Theme.AccentColor
				end)
			end

			local cKey = UserInputService.InputBegan:Connect(function(inp, gpe)
				if listening then
					listening = false
					local newKey = nil
					if inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode ~= Enum.KeyCode.Escape then
						newKey = inp.KeyCode
					elseif inp.UserInputType == Enum.UserInputType.MouseButton1
						or inp.UserInputType == Enum.UserInputType.MouseButton2
						or inp.UserInputType == Enum.UserInputType.MouseButton3 then
						newKey = inp.UserInputType
					end
					if badge then
						badge.TextColor3 = Library.Theme.FontColor
					end
					if newKey then
						kp:SetValue(newKey)
					else
						kp:Display()
					end
					return
				end
				if gpe or Library.Unloaded then
					return
				end
				local curKey = formatKeyName(kp.Value)
				if curKey == "N/A" or curKey == "None" then
					return
				end
				local pressed = false
				if inp.UserInputType == Enum.UserInputType.Keyboard and formatKeyName(inp.KeyCode) == curKey then
					pressed = true
				elseif formatKeyName(inp.UserInputType) == curKey then
					pressed = true
				end
				if pressed then
					if kp.Mode == "Hold" then
						kp:Override(true)
					else
						kp:Override(not kp.State)
					end
					if kp.SyncToggleState and ctrl.Type == "Toggle" then
						ctrl:SetValue(not ctrl.Value)
					elseif kpOpts.Callback then
						pcall(kpOpts.Callback, kp.Value)
					end
				end
			end)
			table.insert(Library.Connections, cKey)

			local cKeyEnd = UserInputService.InputEnded:Connect(function(inp)
				if kp.Mode == "Hold" and kp.State then
					local curKey = formatKeyName(kp.Value)
					if formatKeyName(inp.KeyCode) == curKey or formatKeyName(inp.UserInputType) == curKey then
						kp:Override(false)
					end
				end
			end)
			table.insert(Library.Connections, cKeyEnd)

			Library.Options[kpId] = kp
			Library.Flags[kpId] = kp.Value
			return ctrl
		end

		function ctrl:AddColorPicker(cpId, cpOpts)
			cpOpts = cpOpts or {}
			local defaultCol = cpOpts.Default or Color3.new(1, 1, 1)
			local cp = {
				Type = "ColorPicker",
				Flag = cpId,
				Title = cpOpts.Title or cpId,
				Value = defaultCol,
				Transparency = cpOpts.Transparency or 0,
			}
			local swatch
			if addonsParent then
				swatch = Library:Create("TextButton", {
					Name = "TextButton",
					AnchorPoint = Vector2.new(1, 0.5),
					Position = UDim2.new(1, 0, 0.5, 0),
					Size = UDim2.new(0, 18, 0, 16),
					BorderSizePixel = 1,
					Text = "",
					BackgroundColor3 = defaultCol,
					ZIndex = 3,
					ThemeMap = { BorderColor3 = "OutlineColor" },
					Parent = addonsParent,
				})
			end
			makeControlMethods(cp, function(self, v)
				if swatch and v then
					swatch.BackgroundColor3 = v
				end
			end)
			function cp:SetValueRGB(col, tr)
				self.Value = col
				if tr ~= nil then
					self.Transparency = tr
				end
				self:SetValue(col)
			end
			if cpOpts.Callback then
				cp:OnChanged(cpOpts.Callback)
			end

			if swatch then
				swatch.MouseButton1Click:Connect(function()
					Library:ClosePopups()
					local h, s, v = 0, 0, 1
					pcall(function()
						h, s, v = cp.Value:ToHSV()
					end)
					-- Exact 160x136 HSV popup from mira_ui_tree.json
					local pop = Library:Create("Frame", {
						Name = "Frame",
						BorderSizePixel = 1,
						ZIndex = 60,
						ThemeMap = { BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor" },
						Parent = Library.Popups,
					})
					placePopup(pop, swatch, 160, 136, 0)
					local svBox = Library:Create("Frame", {
						Name = "Frame",
						Position = UDim2.new(0, 8, 0, 8),
						Size = UDim2.new(0, 120, 0, 120),
						BorderSizePixel = 0,
						ZIndex = 61,
						BackgroundColor3 = Color3.fromHSV(h, 1, 1),
						Parent = pop,
					})
					local whiteLayer = Library:Create("Frame", {
						Size = UDim2.fromScale(1, 1),
						BorderSizePixel = 0,
						BackgroundColor3 = Color3.new(1, 1, 1),
						ZIndex = 61,
						Parent = svBox,
					})
					pcall(function()
						local ug = Instance.new("UIGradient")
						ug.Color = ColorSequence.new(Color3.new(1, 1, 1))
						ug.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
						ug.Parent = whiteLayer
					end)
					local blackLayer = Library:Create("Frame", {
						Size = UDim2.fromScale(1, 1),
						BorderSizePixel = 0,
						BackgroundColor3 = Color3.new(0, 0, 0),
						ZIndex = 62,
						Parent = svBox,
					})
					pcall(function()
						local ug = Instance.new("UIGradient")
						ug.Rotation = 90
						ug.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) })
						ug.Parent = blackLayer
					end)
					local svCursor = Library:Create("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.new(s, 0, 1 - v, 0),
						Size = UDim2.new(0, 6, 0, 6),
						BorderSizePixel = 1,
						BorderColor3 = Color3.new(0, 0, 0),
						BackgroundColor3 = Color3.new(1, 1, 1),
						ZIndex = 63,
						Parent = svBox,
					})
					local hueBar = Library:Create("Frame", {
						Name = "Frame",
						Position = UDim2.new(0, 136, 0, 8),
						Size = UDim2.new(0, 14, 0, 120),
						BorderSizePixel = 0,
						ZIndex = 61,
						BackgroundColor3 = Color3.new(1, 1, 1),
						Parent = pop,
					})
					pcall(function()
						local ug = Instance.new("UIGradient")
						ug.Rotation = 90
						ug.Color = ColorSequence.new({
							ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
							ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 255, 0)),
							ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 255, 0)),
							ColorSequenceKeypoint.new(0.50, Color3.fromRGB(0, 255, 255)),
							ColorSequenceKeypoint.new(0.67, Color3.fromRGB(0, 0, 255)),
							ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 0, 255)),
							ColorSequenceKeypoint.new(1.00, Color3.fromRGB(255, 0, 0)),
						})
						ug.Parent = hueBar
					end)
					local hueCursor = Library:Create("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.new(0.5, 0, h, 0),
						Size = UDim2.new(1, 2, 0, 2),
						BorderSizePixel = 1,
						BorderColor3 = Color3.new(0, 0, 0),
						BackgroundColor3 = Color3.new(1, 1, 1),
						ZIndex = 62,
						Parent = hueBar,
					})

					local function syncColor()
						local col = Color3.fromHSV(h, s, v)
						svBox.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
						svCursor.Position = UDim2.new(s, 0, 1 - v, 0)
						hueCursor.Position = UDim2.new(0.5, 0, h, 0)
						cp:SetValueRGB(col)
					end
					syncColor()

					local draggingSV, draggingH = false, false
					local cA = svBox.InputBegan:Connect(function(inp)
						if inp.UserInputType == Enum.UserInputType.MouseButton1 then
							draggingSV = true
						end
					end)
					local cB = hueBar.InputBegan:Connect(function(inp)
						if inp.UserInputType == Enum.UserInputType.MouseButton1 then
							draggingH = true
						end
					end)
					local cC = UserInputService.InputChanged:Connect(function(inp)
						if inp.UserInputType == Enum.UserInputType.MouseMovement and inp.Position then
							if draggingSV and svBox.AbsolutePosition and svBox.AbsoluteSize then
								s = math.clamp((inp.Position.X - svBox.AbsolutePosition.X) / math.max(1, svBox.AbsoluteSize.X), 0, 1)
								v = 1 - math.clamp((inp.Position.Y - svBox.AbsolutePosition.Y) / math.max(1, svBox.AbsoluteSize.Y), 0, 1)
								syncColor()
							elseif draggingH and hueBar.AbsolutePosition and hueBar.AbsoluteSize then
								h = math.clamp((inp.Position.Y - hueBar.AbsolutePosition.Y) / math.max(1, hueBar.AbsoluteSize.Y), 0, 1)
								syncColor()
							end
						end
					end)
					local cD = UserInputService.InputEnded:Connect(function(inp)
						if inp.UserInputType == Enum.UserInputType.MouseButton1 then
							draggingSV = false
							draggingH = false
						end
					end)
					Library._activePopupClose = function()
						pcall(function() cA:Disconnect() end)
						pcall(function() cB:Disconnect() end)
						pcall(function() cC:Disconnect() end)
						pcall(function() cD:Disconnect() end)
						pcall(function() pop:Destroy() end)
					end
				end)
			end

			Library.Options[cpId] = cp
			Library.Flags[cpId] = cp.Value
			return ctrl
		end
		return ctrl
	end

	local function attachContainerMethods(container, parentFrame, ownerTab, ownerSubTab)
		local function focusSearchControl(ctrlHolder)
			if ownerTab and ownerTab.Show then
				ownerTab:Show()
			end
			if ownerSubTab and ownerSubTab.Select then
				ownerSubTab:Select()
			end
			if ctrlHolder then
				ctrlHolder.BackgroundTransparency = 0.7
				if task and task.delay then
					task.delay(0.5, function()
						pcall(function()
							ctrlHolder.BackgroundTransparency = 1
						end)
					end)
				end
			end
		end

		function container:AddToggle(id, opts)
			opts = opts or {}
			local defVal = opts.Default and true or false
			local row = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 20),
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			local outerBox = Library:Create("Frame", {
				Name = "Frame",
				Position = UDim2.new(0, 0, 0.5, 0),
				AnchorPoint = Vector2.new(0, 0.5),
				Size = UDim2.new(0, 13, 0, 13),
				DoubleBorder = true,
				ThemeMap = { BackgroundColor3 = "MainColor" },
				Parent = row,
			})
			local fillBox = Library:Create("Frame", {
				Name = "Frame",
				Position = UDim2.new(0.5, 0, 0.5, 0),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Size = UDim2.new(1, -2, 1, -2),
				BorderSizePixel = 0,
				Visible = defVal,
				ThemeMap = { BackgroundColor3 = "AccentColor" },
				Parent = outerBox,
			})
			local titleColorKey = opts.Risk and "RiskColor" or (opts.Warn and "WarningColor" or "FontColor")
			Library:Create("TextLabel", {
				Name = "TextLabel",
				BackgroundTransparency = 1,
				Position = UDim2.new(0, 20, 0, 0),
				Size = UDim2.new(1, -20, 1, 0),
				FontFace = Library.Font,
				TextSize = 13,
				RichText = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Text = tostring(opts.Text or id),
				ThemeMap = { TextColor3 = titleColorKey },
				Parent = row,
			})
			local hitBtn = Library:Create("TextButton", {
				Name = "TextButton",
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				Text = "",
				ZIndex = 2,
				Parent = row,
			})

			local toggle = {
				Type = "Toggle",
				Flag = id,
				Text = opts.Text or id,
				Value = defVal,
				Tooltip = opts.Tooltip,
			}
			makeControlMethods(toggle, function(self, v)
				fillBox.Visible = v and true or false
			end, row)

			if opts.Callback then
				toggle:OnChanged(opts.Callback)
			end
			hitBtn.MouseButton1Click:Connect(function()
				toggle:SetValue(not toggle.Value)
			end)
			if opts.Tooltip then
				Library:AddTooltip(row, opts.Tooltip)
			end
			toggle.Holder = row
			Library.Toggles[id] = toggle
			Library.Flags[id] = toggle.Value
			Library:RegisterSearchable({
				Text = toggle.Text,
				TabName = ownerTab and ownerTab.Name or "",
				Control = toggle,
				Focus = function() focusSearchControl(row) end,
			})
			return toggle
		end

		function container:AddSlider(id, opts)
			opts = opts or {}
			local mn = opts.Min or 0
			local mx = opts.Max or 100
			local rnd = opts.Rounding or 0
			local suf = opts.Suffix or ""
			local pre = opts.Prefix or ""
			local def = opts.Default ~= nil and opts.Default or mn
			local wrap = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 16),
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			local bar = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.fromScale(1, 1),
				DoubleBorder = true,
				ThemeMap = { BackgroundColor3 = "MainColor" },
				Parent = wrap,
			})
			local fill = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(0, 0, 1, 0),
				BorderSizePixel = 0,
				ThemeMap = { BackgroundColor3 = "AccentColor" },
				Parent = bar,
			})
			local txtLbl = Library:Create("TextLabel", {
				Name = "TextLabel",
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				FontFace = Library.Font,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Center,
				ZIndex = 3,
				ThemeMap = { TextColor3 = "FontColor" },
				Parent = bar,
			})
			local editBox = Library:Create("TextBox", {
				Name = "TextBox",
				Size = UDim2.fromScale(1, 1),
				BorderSizePixel = 0,
				FontFace = Library.Font,
				TextSize = 13,
				Text = "",
				Visible = false,
				ZIndex = 4,
				ThemeMap = { BackgroundColor3 = "MainColor", TextColor3 = "FontColor" },
				Parent = bar,
			})

			local function roundNum(x)
				local mult = 10 ^ rnd
				return math.floor(x * mult + 0.5) / mult
			end

			local slider = {
				Type = "Slider",
				Flag = id,
				Text = opts.Text or id,
				Value = roundNum(math.clamp(def, mn, mx)),
				Min = mn,
				Max = mx,
				Rounding = rnd,
				Suffix = suf,
				Prefix = pre,
				Tooltip = opts.Tooltip,
			}
			local function updateVisual(val)
				local span = math.max(1e-6, mx - mn)
				local frac = math.clamp((val - mn) / span, 0, 1)
				fill.Size = UDim2.new(frac, 0, 1, 0)
				txtLbl.Text = string.format("%s: %s%s%s", tostring(slider.Text), pre, tostring(val), suf)
			end
			updateVisual(slider.Value)

			makeControlMethods(slider, function(self, v)
				local nv = roundNum(math.clamp(tonumber(v) or self.Min, self.Min, self.Max))
				self.Value = nv
				if self.Flag then
					Library.Flags[self.Flag] = nv
				end
				updateVisual(nv)
			end)
			if opts.Callback then
				slider:OnChanged(opts.Callback)
			end

			local dragging = false
			local function applyX(px)
				if bar.AbsolutePosition and bar.AbsoluteSize then
					local frac = math.clamp((px - bar.AbsolutePosition.X) / math.max(1, bar.AbsoluteSize.X), 0, 1)
					slider:SetValue(roundNum(mn + (mx - mn) * frac))
				end
			end
			table.insert(Library.Connections, bar.InputBegan:Connect(function(inp)
				if inp.UserInputType == Enum.UserInputType.MouseButton1 then
					dragging = true
					if inp.Position then
						applyX(inp.Position.X)
					end
				elseif inp.UserInputType == Enum.UserInputType.MouseButton2 then
					editBox.Text = tostring(slider.Value)
					editBox.Visible = true
					pcall(function() editBox:CaptureFocus() end)
				end
			end))
			editBox.FocusLost:Connect(function()
				editBox.Visible = false
				local num = tonumber(editBox.Text)
				if num then
					slider:SetValue(num)
				end
			end)
			table.insert(Library.Connections, UserInputService.InputChanged:Connect(function(inp)
				if dragging and inp.UserInputType == Enum.UserInputType.MouseMovement and inp.Position then
					applyX(inp.Position.X)
				end
			end))
			table.insert(Library.Connections, UserInputService.InputEnded:Connect(function(inp)
				if inp.UserInputType == Enum.UserInputType.MouseButton1 then
					dragging = false
				end
			end))
			if opts.Tooltip then
				Library:AddTooltip(wrap, opts.Tooltip)
			end

			slider.Holder = wrap
			Library.Options[id] = slider
			Library.Flags[id] = slider.Value
			Library:RegisterSearchable({
				Text = slider.Text,
				TabName = ownerTab and ownerTab.Name or "",
				Control = slider,
				Focus = function() focusSearchControl(wrap) end,
			})
			return slider
		end

		function container:AddDropdown(id, opts)
			opts = opts or {}
			local vals = opts.Values or {}
			local isMulti = opts.Multi and true or false
			local def = opts.Default
			if isMulti then
				local map = {}
				if type(def) == "table" then
					for k, v in pairs(def) do
						if type(k) == "number" and type(v) == "string" then
							map[v] = true
						elseif type(k) == "string" and v == true then
							map[k] = true
						end
					end
				end
				def = map
			else
				if type(def) == "number" and vals[def] ~= nil then
					def = vals[def]
				elseif def == nil and not opts.AllowNull then
					def = vals[1]
				end
			end

			local wrap = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 36),
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			Library:Create("TextLabel", {
				Name = "TextLabel",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 14),
				FontFace = Library.Font,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				Text = tostring(opts.Text or id),
				ThemeMap = { TextColor3 = "FontColor" },
				Parent = wrap,
			})
			local selBtn = Library:Create("TextButton", {
				Name = "TextButton",
				Position = UDim2.new(0, 0, 0, 16),
				Size = UDim2.new(1, 0, 0, 20),
				DoubleBorder = true,
				Text = "",
				ThemeMap = { BackgroundColor3 = "MainColor" },
				Padding = { 0, 0, 6, 6 },
				Parent = wrap,
			})
			local valLbl = Library:Create("TextLabel", {
				Name = "TextLabel",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -16, 1, 0),
				FontFace = Library.Font,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				ThemeMap = { TextColor3 = "FontColor" },
				Parent = selBtn,
			})
			Library:Create("TextLabel", {
				Name = "Arrow",
				BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 2, 0.5, 0),
				Size = UDim2.new(0, 12, 0, 12),
				FontFace = Library.Font,
				TextSize = 11,
				Text = "v",
				ThemeMap = { TextColor3 = "FontColorMuted" },
				Parent = selBtn,
			})

			local function summaryText(v)
				if isMulti then
					if type(v) ~= "table" then
						return "---"
					end
					local picked = {}
					for _, cand in ipairs(vals) do
						if v[cand] == true then
							table.insert(picked, tostring(cand))
						end
					end
					for k, on in pairs(v) do
						if on == true and not table.find(vals, k) then
							table.insert(picked, tostring(k))
						end
					end
					return #picked > 0 and table.concat(picked, ", ") or "---"
				end
				return v ~= nil and tostring(v) or "---"
			end

			local dd = {
				Type = "Dropdown",
				Flag = id,
				Text = opts.Text or id,
				Values = vals,
				Value = def,
				Multi = isMulti,
				AllowNull = opts.AllowNull,
				SaveValues = opts.SaveValues,
				Searchable = opts.Searchable,
				Tooltip = opts.Tooltip,
				Open = false,
			}
			valLbl.Text = summaryText(dd.Value)

			makeControlMethods(dd, function(self, v)
				vals = self.Values or {}
				valLbl.Text = summaryText(v)
			end)
			function dd:SetValues(newVals)
				self.Values = newVals or {}
				vals = self.Values
				self:Display()
				return self
			end
			if opts.Callback then
				dd:OnChanged(opts.Callback)
			end

			selBtn.MouseButton1Click:Connect(function()
				local wasOpen = dd.Open
				Library:ClosePopups()
				if wasOpen then
					return
				end
				dd.Open = true
				local popH = math.min(180, math.max(24, #(dd.Values or {}) * 20 + (dd.Searchable and 26 or 4)))
				local pop = Library:Create("Frame", {
					Name = "DropdownList",
					BorderSizePixel = 1,
					ZIndex = 60,
					ThemeMap = { BackgroundColor3 = "MainColor", BorderColor3 = "OutlineColor" },
					Parent = Library.Popups,
				})
				placePopup(pop, selBtn, math.max(120, (selBtn.AbsoluteSize and selBtn.AbsoluteSize.X) or 180), popH, 0)

				local listTop = 1
				local filterBox
				if dd.Searchable then
					listTop = 23
					filterBox = Library:Create("TextBox", {
						Position = UDim2.new(0, 2, 0, 2),
						Size = UDim2.new(1, -4, 0, 18),
						BorderSizePixel = 1,
						FontFace = Library.Font,
						TextSize = 12,
						Text = "",
						PlaceholderText = "search...",
						ZIndex = 61,
						ThemeMap = { BackgroundColor3 = "BackgroundColor", BorderColor3 = "OutlineColor", TextColor3 = "FontColor" },
						Padding = { 0, 0, 4, 4 },
						Parent = pop,
					})
				end
				local scroll = Library:Create("ScrollingFrame", {
					Name = "ScrollingFrame",
					Position = UDim2.new(0, 0, 0, listTop),
					Size = UDim2.new(1, 0, 1, -(listTop + 1)),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					AutomaticCanvasSize = Enum.AutomaticSize.Y,
					CanvasSize = UDim2.new(0, 0, 0, 0),
					ScrollBarThickness = 3,
					ThemeMap = { ScrollBarImageColor3 = "AccentColor" },
					ZIndex = 61,
					Parent = pop,
				})
				Library:Create("UIListLayout", {
					FillDirection = Enum.FillDirection.Vertical,
					Padding = UDim.new(0, 0),
					Parent = scroll,
				})

				local itemBtns = {}
				local function rebuildRows(q)
					for _, b in ipairs(itemBtns) do
						pcall(function() b:Destroy() end)
					end
					itemBtns = {}
					local lq = type(q) == "string" and q:lower() or ""
					for _, itemVal in ipairs(dd.Values or {}) do
						local label = tostring(itemVal)
						if lq == "" or label:lower():find(lq, 1, true) then
							local selected = isMulti and (type(dd.Value) == "table" and dd.Value[itemVal] == true) or (dd.Value == itemVal)
							local optBtn = Library:Create("TextButton", {
								Size = UDim2.new(1, 0, 0, 20),
								BorderSizePixel = 0,
								FontFace = Library.Font,
								TextSize = 13,
								TextXAlignment = Enum.TextXAlignment.Left,
								Text = label,
								ZIndex = 62,
								ThemeMap = {
									BackgroundColor3 = selected and "BackgroundColor" or "MainColor",
									TextColor3 = selected and "AccentColor" or "FontColor",
								},
								Padding = { 0, 0, 6, 6 },
								Parent = scroll,
							})
							optBtn.MouseButton1Click:Connect(function()
								if isMulti then
									local nextTbl = type(dd.Value) == "table" and dd.Value or {}
									if nextTbl[itemVal] then
										nextTbl[itemVal] = nil
									else
										nextTbl[itemVal] = true
									end
									dd:SetValue(nextTbl)
									rebuildRows(filterBox and filterBox.Text or "")
								else
									if dd.AllowNull and dd.Value == itemVal then
										dd:SetValue(nil)
									else
										dd:SetValue(itemVal)
									end
									Library:ClosePopups()
								end
							end)
							table.insert(itemBtns, optBtn)
						end
					end
				end
				rebuildRows("")
				if filterBox then
					filterBox:GetPropertyChangedSignal("Text"):Connect(function()
						rebuildRows(filterBox.Text)
					end)
				end
				Library._activePopupClose = function()
					dd.Open = false
					pcall(function() pop:Destroy() end)
				end
			end)

			if opts.Tooltip then
				Library:AddTooltip(wrap, opts.Tooltip)
			end
			dd.Holder = wrap
			Library.Options[id] = dd
			Library.Flags[id] = dd.Value
			Library:RegisterSearchable({
				Text = dd.Text,
				TabName = ownerTab and ownerTab.Name or "",
				Control = dd,
				Focus = function() focusSearchControl(wrap) end,
			})
			return dd
		end

		function container:AddInput(id, opts)
			opts = opts or {}
			local wrap = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 34),
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			Library:Create("TextLabel", {
				Name = "TextLabel",
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 14),
				FontFace = Library.Font,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				Text = tostring(opts.Text or id),
				ThemeMap = { TextColor3 = "FontColor" },
				Parent = wrap,
			})
			local outer = Library:Create("Frame", {
				Name = "Frame",
				Position = UDim2.new(0, 0, 0, 16),
				Size = UDim2.new(1, 0, 0, 18),
				DoubleBorder = true,
				ThemeMap = { BackgroundColor3 = "MainColor" },
				Padding = { 0, 0, 6, 6 },
				Parent = wrap,
			})
			local box = Library:Create("TextBox", {
				Name = "TextBox",
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				FontFace = Library.Font,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				ClearTextOnFocus = false,
				Text = tostring(opts.Default or ""),
				PlaceholderText = tostring(opts.Placeholder or ""),
				ThemeMap = { TextColor3 = "FontColor", PlaceholderColor3 = "FontColorMuted" },
				Parent = outer,
			})
			local inp = {
				Type = "Input",
				Flag = id,
				Text = opts.Text or id,
				Value = opts.Default or "",
				Placeholder = opts.Placeholder or "",
				Numeric = opts.Numeric,
				Finished = opts.Finished,
			}
			makeControlMethods(inp, function(_, v)
				if box.Text ~= tostring(v or "") then
					box.Text = tostring(v or "")
				end
			end)
			if opts.Callback then
				inp:OnChanged(opts.Callback)
			end
			box.FocusLost:Connect(function()
				local txt = box.Text
				if inp.Numeric and txt ~= "" then
					txt = tostring(tonumber(txt) or inp.Value)
				end
				inp:SetValue(txt)
			end)
			if not opts.Finished then
				box:GetPropertyChangedSignal("Text"):Connect(function()
					if box:IsFocused() then
						inp:SetValue(box.Text)
					end
				end)
			end
			if opts.Tooltip then
				Library:AddTooltip(wrap, opts.Tooltip)
			end
			inp.Holder = wrap
			Library.Options[id] = inp
			Library.Flags[id] = inp.Value
			Library:RegisterSearchable({
				Text = inp.Text,
				TabName = ownerTab and ownerTab.Name or "",
				Control = inp,
				Focus = function() focusSearchControl(wrap) end,
			})
			return inp
		end

		function container:AddButton(textOrOpts, fn)
			local opts = type(textOrOpts) == "table" and textOrOpts or { Text = tostring(textOrOpts), Func = fn }
			local cb = opts.Func or fn
			local rowHolder = Library:Create("Frame", {
				Name = "BtnRow",
				Size = UDim2.new(1, 0, 0, 24),
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			local function makeBtnInst(bOpts, bCb, widthScale, xScale, xOffset, wOffset)
				local btnObj = {
					Type = "Button",
					Text = bOpts.Text or "Button",
					DoubleClick = bOpts.DoubleClick,
					Func = bCb,
				}
				local inst = Library:Create("TextButton", {
					Name = "TextButton",
					Position = UDim2.new(xScale, xOffset, 0, 0),
					Size = UDim2.new(widthScale, wOffset, 1, 0),
					DoubleBorder = true,
					FontFace = Library.Font,
					TextSize = 13,
					TextXAlignment = Enum.TextXAlignment.Center,
					Text = tostring(btnObj.Text),
					ThemeMap = { BackgroundColor3 = "MainColor", TextColor3 = "FontColor" },
					Parent = rowHolder,
				})
				makeControlMethods(btnObj, nil, inst)

				local armed = false
				inst.MouseButton1Click:Connect(function()
					if btnObj.DoubleClick and not armed then
						armed = true
						inst.Text = "Click again to confirm"
						inst.TextColor3 = Library.Theme.WarningColor
						if task and task.delay then
							task.delay(2, function()
								if armed then
									armed = false
									pcall(function()
										inst.Text = tostring(btnObj.Text)
										inst.TextColor3 = Library.Theme.FontColor
									end)
								end
							end)
						end
						return
					end
					armed = false
					inst.Text = tostring(btnObj.Text)
					inst.TextColor3 = Library.Theme.FontColor
					if btnObj.Func then
						pcall(btnObj.Func)
					end
				end)
				if bOpts.Tooltip then
					Library:AddTooltip(inst, bOpts.Tooltip)
				end
				btnObj.Holder = inst
				Library:RegisterSearchable({
					Text = btnObj.Text,
					TabName = ownerTab and ownerTab.Name or "",
					Control = btnObj,
					Focus = function() focusSearchControl(rowHolder) end,
				})
				return btnObj, inst
			end

			local btn, primaryInst = makeBtnInst(opts, cb, 1, 0, 0, 0)
			function btn:AddButton(subOpts, subFn)
				local sOpts = type(subOpts) == "table" and subOpts or { Text = tostring(subOpts), Func = subFn }
				local sCb = sOpts.Func or subFn
				primaryInst.Size = UDim2.new(0.5, -3, 1, 0)
				local subObj = makeBtnInst(sOpts, sCb, 0.5, 0.5, 3, -3)
				return subObj
			end
			return btn
		end

		function container:AddLabel(text, doesWrap)
			local row = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 20),
				AutomaticSize = doesWrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			local lblInst = Library:Create("TextLabel", {
				Name = "TextLabel",
				Size = UDim2.new(1, -26, 1, 0),
				AutomaticSize = doesWrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
				BackgroundTransparency = 1,
				FontFace = Library.Font,
				TextSize = 13,
				RichText = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextWrapped = doesWrap and true or false,
				Text = tostring(text or ""),
				ThemeMap = { TextColor3 = "FontColor" },
				Parent = row,
			})
			local lblObj = {
				Type = "Label",
				Text = tostring(text or ""),
			}
			makeControlMethods(lblObj, nil, row)
			function lblObj:SetText(t)
				self.Text = tostring(t or "")
				lblInst.Text = self.Text
			end
			lblObj.Holder = row
			return lblObj
		end

		function container:AddDivider()
			local wrap = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 7),
				BackgroundTransparency = 1,
				Parent = parentFrame,
			})
			Library:Create("Frame", {
				Name = "Frame",
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 0, 0.5, 0),
				Size = UDim2.new(1, 0, 0, 1),
				BorderSizePixel = 0,
				ThemeMap = { BackgroundColor3 = "OutlineColor" },
