		function container:AddKeyPicker(idx, opts)
			return container:AddLabel((opts and opts.Text) or idx):AddKeyPicker(idx, opts)
		end

		function container:AddColorPicker(idx, opts)
			return container:AddLabel((opts and opts.Text) or idx):AddColorPicker(idx, opts)
		end

		function container:AddDependencyBox()
			local outer = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 0),
				BackgroundTransparency = 1,
				Visible = false,
				Parent = parentFrame,
			})
			local inner = Library:Create("Frame", {
				Name = "Frame",
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				Parent = outer,
			})
			Library:Create("UIListLayout", {
				Padding = UDim.new(0, 6),
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = inner,
			})
			outer.AutomaticSize = Enum.AutomaticSize.Y
			local dep = {
				Holder = outer,
				Dependencies = {},
			}
			attachContainerMethods(dep, inner, ownerTab, ownerSubTab)
			function dep:_evaluate()
				if #self.Dependencies == 0 then
					outer.Visible = true
					return
				end
				local ok = true
				for _, d in ipairs(self.Dependencies) do
					local ctrl, expected = d[1], d[2]
					if ctrl then
						if expected ~= nil and type(ctrl.Value) == "table" and type(expected) ~= "table" then
							if ctrl.Value[expected] ~= true then
								ok = false
								break
							end
						elseif ctrl.Value ~= expected then
							ok = false
							break
						end
					end
				end
				outer.Visible = ok
			end
			function dep:SetupDependencies(deps)
				self.Dependencies = deps or {}
				self:_evaluate()
				return self
			end
			table.insert(Library.DependencyBoxes, dep)
			return dep
		end
	end

	function Library:CreateWindow(opts)
		opts = opts or {}
		local win = {
			Title = opts.Title or "Mira | Rewrite",
			Tabs = {},
			ActiveTab = nil,
		}

		-- Exact Window: 550x550 sharp corners, Bg=BackgroundColor, UIStroke OutlineColor
		local main = self:Create("Frame", {
			Name = "Window",
			Visible = self.Open and not self.Silent,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, 0),
			Size = opts.Size or UDim2.new(0, 550, 0, 550),
			BorderSizePixel = 0,
			ThemeMap = { BackgroundColor3 = "BackgroundColor" },
			Stroke = true,
			Parent = ScreenGui,
		})
		self.MainFrame = main
		self._uiScale = self:Create("UIScale", {
			Scale = self._dpiScale or 1,
			Parent = main,
		})
		self:MakeDraggable(main, 30)

		-- Exact GlowLayer1..4 around Window
		local glowLayers = {}
		for i = 1, 4 do
			local ring = self:Create("Frame", {
				Name = "GlowLayer" .. tostring(i),
				Visible = false,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.new(0.5, 0, 0.5, 0),
				Size = UDim2.new(1, 0, 1, 0),
				BackgroundTransparency = 1,
				ZIndex = 0,
				Corner = 0,
				Parent = main,
			})
			local st = Instance.new("UIStroke")
			st.Thickness = 2 + i * 2
			st.Transparency = 0.65
			st.Color = Library.Theme.AccentColor
			st.Parent = ring
			table.insert(glowLayers, { Frame = ring, Stroke = st, Index = i })
		end

		table.insert(Library.Connections, RunService.RenderStepped:Connect(function()
			if Library.Unloaded then
				return
			end
			if Library.Tooltip and Library.Tooltip.Visible then
				pcall(function()
					local mp = UserInputService:GetMouseLocation()
					Library.Tooltip.Position = UDim2.fromOffset(mp.X + 14, mp.Y + 14)
				end)
			end
			local glowOn = Library.Toggles.EdgeGlow and Library.Toggles.EdgeGlow.Value and main.Visible
			if not glowOn then
				for _, g in ipairs(glowLayers) do
					if g.Frame.Visible then
						g.Frame.Visible = false
					end
				end
				return
			end
			local col = (Library.Options.EdgeGlowColor and Library.Options.EdgeGlowColor.Value) or Library.Theme.AccentColor
			local sz = (Library.Options.EdgeGlowSize and tonumber(Library.Options.EdgeGlowSize.Value)) or 10
			local op = (Library.Options.EdgeGlowOpacity and tonumber(Library.Options.EdgeGlowOpacity.Value)) or 100
			local breathe = Library.Toggles.EdgeGlowBreathe and Library.Toggles.EdgeGlowBreathe.Value
			local pulse = breathe and (0.6 + 0.4 * math.sin(os.clock() * 2.4)) or 1
			local baseAlpha = math.clamp((op / 100) * pulse, 0, 1)
			for _, g in ipairs(glowLayers) do
				g.Frame.Visible = true
				local spread = math.max(2, (sz / 4) * g.Index)
				g.Frame.Size = UDim2.new(1, spread * 2, 1, spread * 2)
				g.Stroke.Color = col
				g.Stroke.Thickness = math.max(1, sz / 3)
				g.Stroke.Transparency = 1 - math.clamp(baseAlpha * (0.42 - g.Index * 0.08), 0, 0.85)
			end
		end))

		-- Exact Title bar (30px, Bg=MainColor) + 1px AccentColor line at y=29
		local titleBar = self:Create("Frame", {
			Name = "Title",
			Size = UDim2.new(1, 0, 0, 30),
			BorderSizePixel = 0,
			ThemeMap = { BackgroundColor3 = "MainColor" },
			Padding = { 0, 0, 12, 12 },
			Parent = main,
		})
		self:Create("TextLabel", {
			Name = "TextLabel",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			FontFace = self.FontBold,
			TextSize = 15,
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = tostring(win.Title),
			ThemeMap = { TextColor3 = "FontColor" },
			Parent = titleBar,
		})
		local searchBox = self:Create("TextBox", {
			Name = "Search",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.new(0, 150, 0, 18),
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			FontFace = self.Font,
			TextSize = 13,
			TextXAlignment = Enum.TextXAlignment.Right,
			ClearTextOnFocus = false,
			Text = "",
			PlaceholderText = "search...",
			ThemeMap = { TextColor3 = "FontColor", PlaceholderColor3 = "FontColorMuted" },
			Parent = titleBar,
		})
		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			local q = searchBox.Text
			Library:ClosePopups()
			if not q or #q < 2 then
				return
			end
			local lq = q:lower()
			local matches = {}
			for _, entry in ipairs(Library.SearchIndex) do
				if entry.Text and entry.Text:lower():find(lq, 1, true) then
					table.insert(matches, entry)
					if #matches >= 12 then
						break
					end
				end
			end
			if #matches == 0 then
				return
			end
			local pop = Library:Create("Frame", {
				Name = "SearchResults",
