	-- Reconstructed Mira Rewrite GUI/ThemeManager matching the full 19-key API
	local HttpService = game:GetService("HttpService")
	local ThemeManager = {}
	ThemeManager.Folder = "Mira-Rewrite/themes"
	ThemeManager.Library = nil
	ThemeManager.DefaultTheme = "Default"
	ThemeManager.pickers = {}
	ThemeManager.themeList = {}

	ThemeManager.BuiltInThemes = {
		Default = {
			1,
			{
				FontColor = "e6cddc",
