			{
				FontColor = "ffffff",
				MainColor = "191919",
				BackgroundColor = "101010",
				AccentColor = "dcdcdc",
				OutlineColor = "464646",
			},
		},
	}

	local function hexToColor3(hex)
		if typeof(hex) == "Color3" then
			return hex
		end
		local s = tostring(hex):gsub("#", "")
		local r = tonumber(s:sub(1, 2), 16) or 255
		local g = tonumber(s:sub(3, 4), 16) or 255
		local b = tonumber(s:sub(5, 6), 16) or 255
		return Color3.fromRGB(r, g, b)
	end

	function ThemeManager:SetLibrary(lib)
		self.Library = lib
	end

	function ThemeManager:SetFolder(folder)
		self.Folder = folder
		self:BuildFolderTree()
	end

	function ThemeManager:BuildFolderTree()
		if not makefolder or not isfolder then
			return
		end
		local parts = {}
		for part in tostring(self.Folder):gmatch("[^/]+") do
			parts[#parts + 1] = part
			local path = table.concat(parts, "/")
			if not isfolder(path) then
				pcall(makefolder, path)
			end
		end
	end

	function ThemeManager:GetCustomTheme(name)
		if not isfile or not readfile then
			return nil
		end
		local path = self.Folder .. "/" .. tostring(name) .. ".json"
		if not isfile(path) then
			return nil
		end
		local ok, decoded = pcall(function()
			return HttpService:JSONDecode(readfile(path))
		end)
		if ok and type(decoded) == "table" then
			return decoded
		end
		return nil
	end

	function ThemeManager:ApplyTheme(name)
		local builtIn = self.BuiltInThemes[name]
		local data = builtIn and builtIn[2] or self:GetCustomTheme(name)
		if not data or not self.Library then
			return
		end
		for k, hex in pairs(data) do
			local c = hexToColor3(hex)
			if self.Library.SetTheme then
				self.Library:SetTheme(k, c)
			end
			if self.pickers[k] and self.pickers[k].SetValueRGB then
				pcall(function()
					self.pickers[k]:SetValueRGB(c)
				end)
			end
		end
	end

	function ThemeManager:UpdateTheme()
		self:ApplyTheme(self.DefaultTheme)
	end

	function ThemeManager:RefreshThemeList()
		local list = {}
		for name in pairs(self.BuiltInThemes) do
			list[#list + 1] = name
		end
		table.sort(list, function(a, b)
			return (self.BuiltInThemes[a][1] or 99) < (self.BuiltInThemes[b][1] or 99)
		end)
		self.themeList = list
		return list
	end

	function ThemeManager:SaveDefault(name)
		if writefile then
			self:BuildFolderTree()
			pcall(writefile, self.Folder .. "/default.txt", tostring(name))
		end
	end

	function ThemeManager:SaveCustomTheme(name)
		if not writefile or not self.Library then
			return
		end
		self:BuildFolderTree()
		local data = {}
		for _, k in ipairs({ "FontColor", "MainColor", "BackgroundColor", "AccentColor", "OutlineColor" }) do
			local c = self.Library.Theme[k]
			if c then
				data[k] = string.format("%02x%02x%02x", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
			end
		end
		pcall(writefile, self.Folder .. "/" .. tostring(name) .. ".json", HttpService:JSONEncode(data))
	end

	function ThemeManager:LoadDefault()
		local theme = self.DefaultTheme
		if isfile and readfile and isfile(self.Folder .. "/default.txt") then
			local ok, txt = pcall(readfile, self.Folder .. "/default.txt")
			if ok and type(txt) == "string" and txt ~= "" then
				theme = txt
			end
		end
		self:ApplyTheme(theme)
	end

	function ThemeManager:CreateThemeManager(groupbox)
		self:ApplyToGroupbox(groupbox)
	end

	function ThemeManager:ApplyToGroupbox(groupbox)
		assert(self.Library, "ThemeManager.Library not set")
		for _, k in ipairs({ "BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor" }) do
			local lbl = groupbox:AddLabel(k)
			if lbl and lbl.AddColorPicker then
				local cp = lbl:AddColorPicker(k, {
					Default = self.Library.Theme[k] or Color3.new(1, 1, 1),
				})
				self.pickers[k] = cp
				if cp and cp.OnChanged then
					cp:OnChanged(function(val)
						self.Library:SetTheme(k, val)
					end)
				end
			end
		end
		groupbox:AddDivider()
		local list = self:RefreshThemeList()
		local dd = groupbox:AddDropdown("ThemeManager_ThemeList", {
			Text = "Theme list",
			Values = list,
			Default = self.DefaultTheme,
			AllowNull = false,
		})
		if dd and dd.OnChanged then
			dd:OnChanged(function(val)
				self:ApplyTheme(val)
			end)
		end
		groupbox:AddButton({
			Text = "Set as default",
			Func = function()
				if dd and dd.Value then
					self:SaveDefault(dd.Value)
					self.Library:Notify("Set default theme to " .. tostring(dd.Value))
				end
			end,
		})
	end

	function ThemeManager:ApplyToTab(tab)
		self:ApplyToGroupbox(tab:AddLeftGroupbox("Themes"))
	end

	ThemeManager:BuildFolderTree()
	return ThemeManager
end

