Modules["Game/EffectTimers"] = function(...)
	local v = ...
	local Signal = v("Utility/Signal")
	local Maid = v("Utility/Maid")
	local Latency = v("Game/Latency")
	local tbl = {}
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local obj = setmetatable({}, { __mode = "k" })
	local v2 = Maid.new()
	local flag = false

	local function fn(arg)
		obj[arg] = { at = os.clock(), debris = arg.DebrisTime }
	end

	tbl.elapsed = function(arg)
		if arg then
			local v3 = obj[arg]

			if v3 then
				local at = v3.at
				local n = os.clock() - at
				return n + (Latency.rdelay() or 0)
			end

			return 0
		end

		return 0
	end

	tbl.remaining = function(arg)
		if arg then
			local v3 = obj[arg]

			if v3 then
				if v3.debris then
					local debris = v3.debris
					local at = v3.at
					return math.max(0, debris - os.clock() - at)
				end

				return nil
			end

			return nil
		end

		return nil
	end

	tbl.forClass = function(arg, arg2)
		local findEffect = arg.FindEffect
		local v3 = findEffect
		local v4 = findEffect(arg, arg2)
		if v4 then
			local remaining = tbl.remaining
			return tbl.elapsed(v4), remaining(v4)
		end
		return nil, nil
	end

	tbl.init = function()
		local rs = game:GetService("ReplicatedStorage")
		return rs:WaitForChild("EffectReplicator")
	end

	tbl.detach = function()
		v2:clean()
		flag = false
	end

	return tbl
end

