Modules["Game/Hooking"] = function(...)
	-- Patched working hooking coordinator matching Mira's Game/Hooking API
	-- Uses hookmetamethod / getnamecallmethod / checkcaller in live executors and safely no-ops in mock checks.
	local tbl = {
		namecallHandlers = {},
		fireServerHandlers = {},
		newindexHandlers = {},
		newindexActive = {},
		neuteredSignals = {},
		droppedRemoteNames = {},
		droppedTelemetryTags = {},
		droppedTelemetryPrefixes = {},
		bans = {},
		inputInterceptor = nil,
		_earlyInited = false,
		_inited = false,
		_active = true,
		_hooksInstalled = false,
		_newindexInstalled = false,
		_oldNamecall = nil,
		_oldNewindex = nil,
	}

	local function installNamecallHook()
		if tbl._hooksInstalled or type(hookmetamethod) ~= "function" then
			return
		end
		tbl._hooksInstalled = true
		local ok, old = pcall(hookmetamethod, game, "__namecall", function(self, ...)
			local orig = tbl._oldNamecall
			if not orig then
				return nil
			end
			if not tbl._active then
				return orig(self, ...)
			end
			local method = type(getnamecallmethod) == "function" and getnamecallmethod() or nil
			local isCaller = type(checkcaller) == "function" and checkcaller() or false
			if method == "FireServer" or method == "InvokeServer" then
				if method == "FireServer" and tbl.droppedRemoteNames[tostring(self)] then
					return
				end
				local fsHandler = tbl.fireServerHandlers[self]
				if fsHandler then
					local res = table.pack(pcall(fsHandler, self, orig, ...))
					if res[1] then
						return table.unpack(res, 2, res.n)
					end
				end
				local ii = tbl.inputInterceptor
				if ii and ii.classify and ii.run and typeof(self) == "Instance" then
					local okCls, cls = pcall(ii.classify, self, method == "InvokeServer")
					if (not okCls or cls == nil) and self.Name == "ActivateMantra" then
						okCls, cls = pcall(ii.classify, self, true)
					end
					if okCls and cls ~= nil then
						return ii.run(cls, self, orig, isCaller, ...)
					end
				end
			end
			if method then
				local ncHandler = tbl.namecallHandlers[method]
				if ncHandler then
					local res = table.pack(pcall(ncHandler, self, orig, ...))
					if res[1] then
						return table.unpack(res, 2, res.n)
					end
				end
			end
			return orig(self, ...)
		end)
		if ok and type(old) == "function" then
			tbl._oldNamecall = old
		else
			tbl._hooksInstalled = false
		end
	end

	function tbl.ensureNewindexHook()
		if tbl._newindexInstalled or type(hookmetamethod) ~= "function" then
			return true
		end
		tbl._newindexInstalled = true
		local ok, old = pcall(hookmetamethod, game, "__newindex", function(self, k, v)
			local orig = tbl._oldNewindex
			if not orig then
				return nil
			end
			if tbl._active and not (type(checkcaller) == "function" and checkcaller()) then
				if tbl.newindexActive[k] then
					local niHandler = tbl.newindexHandlers[k]
					if niHandler then
						local res = table.pack(pcall(niHandler, self, orig, k, v))
						if res[1] then
							return table.unpack(res, 2, res.n)
						end
					end
				end
			end
			return orig(self, k, v)
		end)
		if ok and type(old) == "function" then
			tbl._oldNewindex = old
		else
			tbl._newindexInstalled = false
		end
		return true
	end

	function tbl.onNamecall(method, fn)
		if method == nil then
			return
		end
		if type(method) == "function" and fn == nil then
			tbl.namecallHandlers[method] = method
		elseif fn == nil then
			tbl.namecallHandlers[method] = nil
		elseif type(fn) == "function" then
			tbl.namecallHandlers[method] = fn
		end
		installNamecallHook()
	end

	function tbl.onFireServer(remote, fn)
		if remote == nil then
			return
		end
		if type(remote) == "function" and fn == nil then
			tbl.fireServerHandlers[remote] = remote
		elseif fn == nil then
			tbl.fireServerHandlers[remote] = nil
		elseif type(fn) == "function" then
			tbl.fireServerHandlers[remote] = fn
		end
		installNamecallHook()
	end

	function tbl.onNewindex(tag, fn)
		if tag == nil then
			return
		end
		if fn == nil then
			tbl.newindexHandlers[tag] = nil
		elseif type(fn) == "function" then
			tbl.newindexHandlers[tag] = fn
			tbl.ensureNewindexHook()
		end
	end

	function tbl.setNewindexActive(tag, active)
		if tag ~= nil then
			tbl.newindexActive[tag] = active and true or false
			if active then
				tbl.ensureNewindexHook()
			end
		end
	end

