Modules["Game/Objects/DodgeOptions"] = function(...)
	-- Repaired Game/Objects/DodgeOptions
	local index = {}
	index.__index = index

	index.new = function()
		local obj = setmetatable({}, index)
		obj.rollCancel = false
		obj.rollCancelDelay = 0
		obj.direct = false
		obj.actionRolling = false
		obj.full = false
		return obj
	end

	return index
end

-- ----------------------------------------------------------------------------
-- Module: Game/Player (funcs=4, orig_lines=31)
-- ----------------------------------------------------------------------------
Modules["Game/Player"] = function(...)
	-- Repaired Game/Player tracker
	local Players = game:GetService("Players")
	local localPlayer = Players.LocalPlayer
	local tbl = {
		instance = localPlayer,
		character = nil,
		root = nil,
		humanoid = nil,
	}

	local function updateCharacter(character)
		tbl.character = character
		if character then
			tbl.root = character:FindFirstChild("HumanoidRootPart")
			tbl.humanoid = character:FindFirstChildOfClass("Humanoid")
		else
			tbl.root = nil
			tbl.humanoid = nil
		end
	end

	if localPlayer then
		updateCharacter(localPlayer.Character)
		if localPlayer.CharacterAdded then
			localPlayer.CharacterAdded:Connect(function(character)
				pcall(function()
					character:WaitForChild("HumanoidRootPart", 5)
				end)
				updateCharacter(character)
			end)
		end
	end

	return tbl
end

