-- Module: Game/Tweening (funcs=1, orig_lines=2)
-- ----------------------------------------------------------------------------
Modules["Game/Tweening"] = function(...)
	-- Clean Game/Tweening coordinator matching 5-key API
	local tbl = {
		active = false,
		queue = {},
	}

	function tbl.current()
		return tbl.queue[1]
	end

	function tbl.goal(target, props)
		tbl.active = true
		table.insert(tbl.queue, { target = target, props = props })
	end

	function tbl.stop()
		tbl.active = false
		table.clear(tbl.queue)
	end

	return tbl
end

