-- ----------------------------------------------------------------------------
-- Module Loader & Entry Point
-- ----------------------------------------------------------------------------
local LoadedModules = {}
local function requireModule(name)
	if type(name) ~= "string" then
		if type(require) == "function" then
			return require(name)
		end
		return name
	end
	if LoadedModules[name] ~= nil then
		return LoadedModules[name]
	end
	local factory = Modules[name]
	if not factory then
		error("Mira module not found: " .. tostring(name))
	end
	local result = factory(requireModule)
	LoadedModules[name] = result
	return result
end

return requireModule("__root")
